  process.sleep_forever()
}

fn start_handler(req: http.Request) -> http.Response {
  case req.path_segments {
    [] -> http.response(200, json.to_string(json.object([#("status", json.string("JAIDE V31 KAN LLM ready"))])))
    ["infer"] -> {
      let assert Ok(body) = http.body(req)
