pub type Matrix = List(List(Float))

pub fn random(rows: Int, cols: Int) -> Matrix {
  list.map(list.range(0, rows), fn(_) {
    list.map(list.range(0, cols), fn(_) {
      float.random() - 0.5
    })
  })
}

pub fn from_list(data: List(List(Float))) -> Matrix {
  data
}

pub fn flatten(m: Matrix) -> List(Float) {
  list.flat_map(m, fn(row) { row })
}

pub fn cols(m: Matrix) -> Int {
  case m {
    [] -> 0
    [first, ..] -> list.length(first)
  }
}

pub fn rows(m: Matrix) -> Int {
  list.length(m)
}

pub fn add_row_vector(m: Matrix, vec: List(Float)) -> Matrix {
  let n = cols(m)
  let vec_pad = if list.length(vec) < n {
    list.append(vec, list.repeat(0.0, n - list.length(vec)))
  } else {
    list.take(vec, n)
  }
  list.map(m, fn(row) {
    list.map2(row, vec_pad, fn(r, v) { r + v })
  })
}

pub fn relu(m: Matrix) -> Matrix {
  list.map(m, fn(row) {
    list.map(row, fn(x) { float.max(0.0, x) })
  })
}

pub fn max(m: Matrix) -> Float {
  flatten(m) |> list.fold(0.0, fn(acc, x) { float.max(acc, x) })
}

pub fn map(m: Matrix, f: fn(Float) -> Float) -> Matrix {
  list.map(m, fn(row) {
    list.map(row, f)
  })
}

pub fn sum(m: Matrix) -> Float {
  flatten(m) |> list.fold(0.0, fn(acc, x) { acc + x })
}

pub fn log(m: Matrix) -> Matrix {
  map(m, float.log)
}

pub fn multiply(m1: Matrix, m2: Matrix) -> Matrix {
  let r1 = rows(m1)
  let r2 = rows(m2)
  if r1 != r2 {
    m1
  } else {
    list.map2(m1, m2, fn(row1, row2) {
      let c1 = list.length(row1)
      let c2 = list.length(row2)
      if c1 != c2 {
        row1
      } else {
        list.map2(row1, row2, fn(r, t) { r * t })
      }
    })
  }
}

pub fn scale(m: Matrix, s: Float) -> Matrix {
  map(m, fn(x) { x * s })
}

pub fn top_k_indices(m: Matrix, k: Int) -> List(Int) {
  let flat = flatten(m)
  let indexed = list.index_map(flat, fn(i, v) { #(v, i) })
  let sorted = list.sort(indexed, fn(a, b) { float.compare(b.0, a.0) })
  sorted |> list.take(k) |> list.map(fn(pair) { pair.1 })
}

pub fn argmax_row(m: Matrix) -> Int {
  case m {
    [] -> 0
    [row, ..] -> {
      let indexed = list.index_map(row, fn(i, v) { #(v, i) })
      let sorted = list.sort(indexed, fn(a, b) { float.compare(b.0, a.0) })
      case list.head(sorted) {
        Ok(pair) -> pair.1
        Error(_) -> 0
      }
    }
    _ -> 0
  }
}

pub fn onehot(rows: Int, cols: Int, index: Int) -> Matrix {
  list.map(list.range(0, rows), fn(_) {
    list.map(list.range(0, cols), fn(i) {
      if i == index { 1.0 } else { 0.0 }
    })
  })
}

pub fn stack_rows(chunks: List(Matrix)) -> Matrix {
  list.flat_map(chunks, fn(mat) { mat })
}

pub fn shape(m: Matrix) -> #(Int, Int) {
  #(rows(m), cols(m))
}

pub fn transpose(m: Matrix) -> Matrix {
  list.range(0, cols(m))
  |> list.map(fn(c) {
    list.map(m, fn(row) {
      list.at(row, c) |> result.unwrap(0.0)
    })
  })
}

pub fn get_column(m: Matrix, col: Int) -> List(Float) {
  list.map(m, fn(row) {
    list.at(row, col) |> result.unwrap(0.0)
  })
}

pub fn set_column(m: Matrix, col: Int, vec: List(Float)) -> Matrix {
  list.map2(m, vec, fn(row, v) {
    list.update(row, col, fn(_) { v })
  })
}

pub fn get_element(m: Matrix, row: Int, col: Int) -> Float {
  list.at(m, row)
  |> result.unwrap([])
  |> list.at(_, col)
  |> result.unwrap(0.0)
}

pub fn get_row(m: Matrix, row: Int) -> List(Float) {
  list.at(m, row) |> result.unwrap([])
}

pub fn take_columns(m: Matrix, n: Int) -> Matrix {
  list.map(m, fn(row) { list.take(row, n) })
}

pub fn drop_columns(m: Matrix, n: Int) -> Matrix {
  list.map(m, fn(row) { list.drop(row, n) })
}

pub fn concatenate_columns(m1: Matrix, m2: Matrix) -> Matrix {
  list.map2(m1, m2, fn(r1, r2) {
    list.append(r1, r2)
  })
}

pub fn multiply_submatrix(m: Matrix, sub: Matrix, start_row: Int, start_col: Int, size_row: Int, size_col: Int) -> Matrix {
  list.index_map(m, fn(i, row) {
    if i >= start_row && i < start_row + size_row {
      list.index_map(row, fn(j, v) {
        if j >= start_col && j < start_col + size_col {
          let sub_row = i - start_row
          let sub_col = j - start_col
          let sub_val = get_element(sub, sub_row, sub_col)
          sub_val
        } else {
          v
        }
      })
    } else {
      row
    }
  })
}

pub fn subtract(m1: Matrix, m2: Matrix) -> Matrix {
  list.map2(m1, m2, fn(r1, r2) {
    list.map2(r1, r2, fn(v1, v2) { v1 - v2 })
  })
}

pub fn ones(rows: Int, cols: Int) -> Matrix {
  list.repeat(list.repeat(1.0, cols), rows)
}

pub fn subtract_submatrix(m1: Matrix, m2: Matrix) -> Matrix {
  subtract(m1, m2)
}

pub fn add(m1: Matrix, m2: Matrix) -> Matrix {
  list.map2(m1, m2, fn(r1, r2) {
    list.map2(r1, r2, fn(v1, v2) { v1 + v2 })
  })
}

pub type Vocab {
  Vocab(mapping: map.Map(String, Int), reverse: map.Map(Int, String))
}

pub fn load_vocab(path: String) -> Vocab {
  let assert Ok(content) = bit_string.from_file(path)
  let assert Ok(decoded) = json.decode(content, dynamic.object)
  let mapping_list = dynamic.to_list(decoded)
    |> list.map(fn(pair) {
      let assert #(key, value) = pair
      let assert Ok(id) = dynamic.int(value)
      #(key, id)
    })
  let mapping = map.from_list(mapping_list)
  let reverse_list = list.map(map.to_list(mapping), fn(pair) {
    let #(k, v) = pair
    #(v, k)
  })
  let reverse = map.from_list(reverse_list)
  Vocab(mapping: mapping, reverse: reverse)
}

pub fn tokenize(vocab: Vocab, text: String) -> List(Int) {
  let normalized = normalize_text(text)
  normalized
  |> string.to_graphemes
  |> list.map(fn(grapheme) {
    map.get(vocab.mapping, grapheme) |> result.unwrap(3)
  })
}

pub fn detokenize(vocab: Vocab, ids: List(Int)) -> String {
  ids
  |> list.map(fn(id) {
    map.get(vocab.reverse, id) |> result.unwrap("UNK")
  })
  |> string.concat
}

fn normalize_text(text: String) -> String {
  text
  |> string.lowercase
  |> string.replace("-", " ")
  |> string.replace("—", " ")
  |> string.trim
}

pub type Token {
  Token(id: Int, embedding: List(Float))
}

pub fn standard_embedding_for_token(id: Int, index: Int) -> List(Float) {
  let dim = 9216
  let scale = 1.0 / float.sqrt(float.from_int(dim))
  list.map(list.range(0, dim), fn(i) {
    let phase = float.sin(float.from_int(i) * float.from_int(index) * scale)
    phase * float.from_int(id) * scale
  })
}

pub fn tokenize_with_embeddings(text: String, vocab: Vocab) -> List(Token) {
  let ids = tokenize(vocab, text)
  ids
  |> list.index_map(fn(index, id) {
    let embedding = standard_embedding_for_token(id, index)
    Token(id: id, embedding: embedding)
  })
}

pub type KANLayer {
  KANLayer(spline_coeffs: List(List(Float)), grid_size: Int, input_dim: Int, output_dim: Int)
}

pub type KANNetwork {
  KANNetwork(layers: List(KANLayer), dim: Int, grid_size: Int)
}

pub fn initialize_kan_network(dim: Int, grid_size: Int, layers: Int) -> KANNetwork {
  let layers_list = list.map(list.range(0, layers), fn(_) {
    let spline_coeffs = list.map(list.range(0, dim), fn(_) {
      list.map(list.range(0, grid_size), fn(_) {
        float.random() - 0.5
      })
    })
    KANLayer(spline_coeffs: spline_coeffs, grid_size: grid_size, input_dim: dim, output_dim: dim)
  })
  KANNetwork(layers: layers_list, dim: dim, grid_size: grid_size)
}

pub fn kan_forward_pass(network: KANNetwork, input: Matrix) -> Matrix {
  list.fold(network.layers, input, fn(acc, layer) {
    let spline_eval = evaluate_splines(layer.spline_coeffs, acc, layer.grid_size)
    let bias_vec = list.repeat(0.0, layer.output_dim)
    let add_bias = add_row_vector(spline_eval, bias_vec)
    relu(add_bias)
  })
}

fn evaluate_splines(coeffs: List(List(Float)), input: Matrix, grid_size: Int) -> Matrix {
  let output = list.map(list.zip(flatten(input), coeffs), fn(pair) {
    let #(x, col) = pair
    spline_interpolate(x, col, grid_size)
  })
  from_list([output])
}

fn spline_interpolate(x: Float, coeffs: List(Float), grid_size: Int) -> Float {
  let knots = list.map(list.range(0, grid_size), fn(i) {
    float.from_int(i) / float.from_int(grid_size - 1)
  })
  let basis = b_spline_basis(x, knots, 3)
  dot_product(basis, coeffs)
}

fn dot_product(a: List(Float), b: List(Float)) -> Float {
  list.map2(a, b, fn(x, y) { x * y }) |> list.sum
}

fn b_spline_basis(x: Float, knots: List(Float), degree: Int) -> List(Float) {
  if degree == 0 {
    list.map(knots, fn(k) {
      let idx = list.index_of(knots, k) |> result.unwrap(0)
      let next_k = list.at(knots, idx + 1) |> result.unwrap(k + 1.0)
      if x >= k && x < next_k { 1.0 } else { 0.0 }
    })
  } else {
    let dropped = list.drop(knots, 1)
    let left = b_spline_basis(x, dropped, degree - 1)
    let right = b_spline_basis(x, dropped, degree - 1)
    let first_k = list.at(knots, 0) |> result.unwrap(0.0)
    let last_k = list.at(knots, list.length(knots) - 1) |> result.unwrap(1.0)
    let denom = if last_k - first_k > 0.0 { last_k - first_k } else { 1.0 }
    let alpha = (x - first_k) / denom
    list.map2(left, right, fn(l, r) { alpha * l + (1.0 - alpha) * r })
  }
}

pub fn cross_entropy_loss(outputs: List(Matrix), targets: List(Matrix)) -> Float {
  list.zip(outputs, targets)
  |> list.fold(0.0, fn(acc, pair) {
    let output = pair.0
    let target = pair.1
    let probs = softmax(output)
    let log_probs = log(probs)
    let nll = sum(multiply(log_probs, target))
    acc - nll
  })
}

fn softmax(matrix: Matrix) -> Matrix {
  let max_val = max(matrix)
  let exp_vals = map(matrix, fn(x) { float.exp(x - max_val) })
  let sum_exp = sum(exp_vals)
  map(exp_vals, fn(x) { x / sum_exp })
}

pub fn adam_update(network: KANNetwork, grads: KANNetwork, lr: Float, beta1: Float, beta2: Float, eps: Float, t: Int) -> KANNetwork {
  let updated_layers = list.map3(network.layers, grads.layers, list.range(0, list.length(network.layers)), fn(layer, grad_layer, _) {
    let g_coeffs = grad_layer.spline_coeffs
    let m_coeffs = list.map(g_coeffs, fn(col) {
      list.map(col, fn(g) { g * (1.0 - beta1) })
    })
    let v_coeffs = list.map(g_coeffs, fn(col) {
      list.map(col, fn(g) { g * g * (1.0 - beta2) })
    })
    let m_hat = list.map(m_coeffs, fn(col) {
      list.map(col, fn(c) {
        c / (1.0 - float.pow(beta1, float.from_int(t + 1)))
      })
    })
    let v_hat = list.map(v_coeffs, fn(col) {
      list.map(col, fn(c) {
        c / (1.0 - float.pow(beta2, float.from_int(t + 1)))
      })
    })
    let new_coeffs = list.map3(layer.spline_coeffs, m_hat, v_hat, fn(col, mh, vh) {
      list.map3(col, mh, vh, fn(c, m, v) {
        let sqrt_v = float.sqrt(v + eps)
        c - lr * m / sqrt_v
      })
    })
    KANLayer(spline_coeffs: new_coeffs, grid_size: layer.grid_size, input_dim: layer.input_dim, output_dim: layer.output_dim)
  })
  KANNetwork(layers: updated_layers, dim: network.dim, grid_size: network.grid_size)
}

pub fn quantize_kan_layer(layer: KANLayer, bits: Int) -> KANLayer {
  let scale = float.pow(2.0, float.from_int(bits))
  let quantized_coeffs = list.map(layer.spline_coeffs, fn(col) {
    list.map(col, fn(c) {
      float.round(c / scale) * scale
    })
  })
  KANLayer(spline_coeffs: quantized_coeffs, grid_size: layer.grid_size, input_dim: layer.input_dim, output_dim: layer.output_dim)
}

pub fn training_loop(network: KANNetwork, dataset: List(#(Matrix, Matrix)), epochs: Int, batch_size: Int, lr: Float) -> KANNetwork {
  list.range(0, epochs)
  |> list.fold(network, fn(acc_network, epoch) {
    let batches = batch_dataset(dataset, batch_size)
    list.fold(batches, acc_network, fn(acc, batch) {
      let inputs = list.map(batch, fn(pair) { pair.0 })
      let targets = list.map(batch, fn(pair) { pair.1 })
      let outputs = list.map(inputs, fn(input) {
        kan_forward_pass(acc, input)
      })
      let loss = cross_entropy_loss(outputs, targets)
      let grads = compute_kan_gradients(acc, inputs, targets)
      adam_update(acc, grads, lr, 0.9, 0.999, 1.0e-12, epoch)
    })
  })
}

fn batch_dataset(dataset: List(#(Matrix, Matrix)), batch_size: Int) -> List(List(#(Matrix, Matrix))) {
  list.chunk(dataset, batch_size)
}

fn compute_kan_gradients(network: KANNetwork, inputs: List(Matrix), targets: List(Matrix)) -> KANNetwork {
  let dummy_layers = list.map(network.layers, fn(layer) {
    let dummy_coeffs = list.map(list.range(0, network.dim), fn(_) {
      list.map(list.range(0, network.grid_size), fn(_) { 0.01 })
    })
    KANLayer(spline_coeffs: dummy_coeffs, grid_size: network.grid_size, input_dim: network.dim, output_dim: network.dim)
  })
  KANNetwork(layers: dummy_layers, dim: network.dim, grid_size: network.grid_size)
}

pub fn run_pipeline(config_path: String, dataset_path: String) -> Nil {
  let assert Ok(config_content) = bit_string.from_file(config_path)
  let assert Ok(config) = json.decode(config_content, dynamic.dict(dynamic.string, dynamic.dynamic))
  let assert Ok(training_config) = map.get(config, "training_config")
  let assert Ok(batch_size) = dynamic.field(training_config, "batch_size") |> result.then(dynamic.int)
  let assert Ok(epochs) = dynamic.field(training_config, "epochs") |> result.then(dynamic.int)
  let assert Ok(optimizer_config) = map.get(config, "optimizer_config")
  let assert Ok(lr) = dynamic.field(optimizer_config, "lr") |> result.then(dynamic.float)
  let vocab = load_vocab("vocab.json")
  let dataset = load_dataset(dataset_path, vocab)
  let network = initialize_kan_network(9216, 5, 256)
  let trained = training_loop(network, dataset, epochs, batch_size, lr)
  save_checkpoint(trained, "kan_checkpoint.bin")
  io.println("KAN Training pipeline completed")
  Nil
}

fn load_dataset(path: String, vocab: Vocab) -> List(#(Matrix, Matrix)) {
  let assert Ok(content) = bit_string.from_file(path)
  let assert Ok(decoded) = json.decode(content, dynamic.list(dynamic.dict(dynamic.string, dynamic.dynamic)))
  decoded
  |> list.map(fn(item) {
    let assert Ok(text) = map.get(item, "text") |> result.then(dynamic.string)
    let assert Ok(label) = map.get(item, "label") |> result.then(dynamic.int)
    let tokens = tokenize_with_embeddings(text, vocab)
    let input_emb = tokens_to_matrix(tokens)
    let target = label_to_onehot(label)
    #(input_emb, target)
  })
}

fn tokens_to_matrix(tokens: List(Token)) -> Matrix {
  list.map(tokens, fn(t) { t.embedding })
}

fn label_to_onehot(label: Int) -> Matrix {
  let onehot = list.map(list.range(0, 20), fn(i) {
    if i == label { 1.0 } else { 0.0 }
  })
  [onehot]
}

fn save_checkpoint(network: KANNetwork, path: String) -> Nil {
  let serialized_layers = list.map(network.layers, fn(layer) {
    let spline_json = json.array(list.map(layer.spline_coeffs, fn(col) {
      json.array(list.map(col, json.float))
    }))
    json.object([
      #("spline_coeffs", spline_json),
      #("grid_size", json.int(layer.grid_size)),
      #("input_dim", json.int(layer.input_dim)),
      #("output_dim", json.int(layer.output_dim)),
    ])
  })
  let checkpoint = json.object([
    #("dim", json.int(network.dim)),
    #("grid_size", json.int(network.grid_size)),
    #("layers", json.array(serialized_layers)),
  ])
  let assert Ok(_) = bit_string.to_file(path, json.to_string(checkpoint))
  Nil
}

pub fn create_batch(inputs: List(Matrix), targets: List(Matrix), batch_size: Int) -> List(#(Matrix, Matrix)) {
  let batched_inputs = list.chunk(inputs, batch_size)
    |> list.map(fn(chunk) { stack_rows(chunk) })
  let batched_targets = list.chunk(targets, batch_size)
    |> list.map(fn(chunk) { stack_rows(chunk) })
  list.zip(batched_inputs, batched_targets)
}

pub fn pad_batch(batch: List(Matrix), max_len: Int) -> List(Matrix) {
  list.map(batch, fn(mat) {
    let r = rows(mat)
    if r < max_len {
      let padding = list.repeat(list.repeat(0.0, cols(mat)), max_len - r)
      list.append(mat, padding)
    } else {
      mat
    }
  })
}

pub fn quantize_kan_network(network: KANNetwork, bits: Int) -> KANNetwork {
  let quantized_layers = list.map(network.layers, fn(layer) {
    quantize_kan_layer(layer, bits)
  })
  KANNetwork(layers: quantized_layers, dim: network.dim, grid_size: network.grid_size)
}

pub fn dequantize_kan_layer(layer: KANLayer, original_scale: Float) -> KANLayer {
  let dequant_coeffs = list.map(layer.spline_coeffs, fn(col) {
    list.map(col, fn(c) { c * original_scale })
  })
  KANLayer(spline_coeffs: dequant_coeffs, grid_size: layer.grid_size, input_dim: layer.input_dim, output_dim: layer.output_dim)
}

pub fn xavier_init(dim: Int) -> Matrix {
  let scale = float.sqrt(6.0 / float.from_int(2 * dim))
  map(random(dim, dim), fn(x) { x * scale })
}

pub fn spectral_init(dim: Int, spectral_target: Float) -> Matrix {
  let scale = spectral_target / float.sqrt(float.from_int(dim))
  map(random(dim, dim), fn(x) { x * scale })
}

pub fn clean_text(text: String) -> String {
  let assert Ok(lower_regex) = regex.from_string("[A-Z]")
  let lowered = regex.replace(lower_regex, text, fn(c) {
    string.lowercase(c.matched)
  })
  let assert Ok(punct_regex) = regex.from_string("[^a-z0-9\\s]")
  let no_punct = regex.replace(punct_regex, lowered, fn(_) { "" })
  string.trim(no_punct)
}

pub fn augment_text(text: String) -> List(String) {
  [text, string.reverse(text), string.uppercase(text), string.lowercase(text)]
}

pub fn top_k_sampling(logits: Matrix, k: Int, temperature: Float) -> Int {
  let scaled = scale(logits, 1.0 / temperature)
  let probs = softmax(scaled)
  let top_indices = top_k_indices(probs, k)
  case list.head(top_indices) {
    Ok(idx) -> idx
    Error(_) -> 0
  }
}

pub fn nucleus_sampling(logits: Matrix, p: Float, temperature: Float) -> Int {
  let scaled = scale(logits, 1.0 / temperature)
  let probs = softmax(scaled)
  let flat = flatten(probs)
  let sorted = list.sort(flat, fn(a, b) { float.compare(b, a) })
  let cum = list.scan(sorted, 0.0, fn(acc, pr) { acc + pr })
  let num = list.take_while(cum, fn(c) { c < p }) |> list.length
  case list.at(list.range(0, num), 0) {
    Ok(idx) -> idx
    Error(_) -> 0
  }
}

pub fn generate_text(network: KANNetwork, vocab: Vocab, prompt: String, max_tokens: Int, method: String) -> String {
  let ids = tokenize(vocab, prompt)
  let generated = list.range(0, max_tokens)
  |> list.fold(ids, fn(acc, _) {
    let current = [list.map(acc, fn(id) {
      list.repeat(float.from_int(id) / 9216.0, 9216)
    })]
    let logits = kan_forward_pass(network, current)
    let next_id = case method {
      "top_k" -> top_k_sampling(logits, 50, 0.6)
      "nucleus" -> nucleus_sampling(logits, 0.95, 0.6)
      _ -> nucleus_sampling(logits, 0.95, 0.6)
    }
    list.append(acc, [next_id])
  })
  detokenize(vocab, generated)
}

pub fn validate(network: KANNetwork, val_dataset: List(#(Matrix, Matrix))) -> Float {
  let outputs = list.map(val_dataset, fn(pair) {
    kan_forward_pass(network, pair.0)
  })
  let targets = list.map(val_dataset, fn(pair) { pair.1 })
  cross_entropy_loss(outputs, targets)
}

pub fn test_accuracy(network: KANNetwork, test_dataset: List(#(Matrix, Matrix))) -> Float {
  let predictions = list.map(test_dataset, fn(pair) {
    let output = kan_forward_pass(network, pair.0)
    argmax_row(output)
  })
  let true_labels = list.map(test_dataset, fn(pair) {
    argmax_row(pair.1)
  })
  let correct = list.zip(predictions, true_labels)
    |> list.count(fn(pair) { pair.0 == pair.1 })
  float.from_int(correct) / float.from_int(list.length(test_dataset))
}

pub fn save_weights(network: KANNetwork, path: String) -> Nil {
  save_checkpoint(network, path)
}

pub fn load_weights(path: String) -> KANNetwork {
  let assert Ok(content) = bit_string.from_file(path)
  let assert Ok(decoded) = json.decode(content, dynamic.dict(dynamic.string, dynamic.dynamic))
  let assert Ok(dim) = map.get(decoded, "dim") |> result.then(dynamic.int)
  let assert Ok(grid_size) = map.get(decoded, "grid_size") |> result.then(dynamic.int)
  let assert Ok(layers_json) = map.get(decoded, "layers") |> result.then(dynamic.list(dynamic.dict(dynamic.string, dynamic.dynamic)))
  let layers = list.map(layers_json, fn(l_json) {
    let assert Ok(spline_coeffs_json) = map.get(l_json, "spline_coeffs") |> result.then(dynamic.list(dynamic.list(dynamic.float)))
    let spline_coeffs = spline_coeffs_json
    let assert Ok(g_size) = map.get(l_json, "grid_size") |> result.then(dynamic.int)
    let assert Ok(in_dim) = map.get(l_json, "input_dim") |> result.then(dynamic.int)
    let assert Ok(out_dim) = map.get(l_json, "output_dim") |> result.then(dynamic.int)
    KANLayer(spline_coeffs: spline_coeffs, grid_size: g_size, input_dim: in_dim, output_dim: out_dim)
  })
  KANNetwork(layers: layers, dim: dim, grid_size: grid_size)
}

pub fn infer(network_path: String, vocab_path: String, prompt: String, config: String) -> String {
  let network = load_weights(network_path)
  let vocab = load_vocab(vocab_path)
  let assert Ok(content) = bit_string.from_file(config)
  let assert Ok(decoded) = json.decode(content, dynamic.dict(dynamic.string, dynamic.dynamic))
  let assert Ok(inference_config) = map.get(decoded, "inference_config")
  let assert Ok(method) = dynamic.field(inference_config, "sampling_method") |> result.then(dynamic.string)
  let assert Ok(max_tokens) = dynamic.field(inference_config, "max_tokens") |> result.then(dynamic.int)
  generate_text(network, vocab, prompt, max_tokens, method)
}

pub fn accelerate_kan_forward(network: KANNetwork, input: Matrix) -> Matrix {
  kan_forward_pass(network, input)
}

pub fn distributed_train(config: String) -> Nil {
  io.println("Distributed training initiated with config: " <> config)
  Nil
}

pub fn sync_kan_gradients(grads: List(Matrix)) -> List(Matrix) {
  let n = float.from_int(list.length(grads))
  list.map(grads, fn(g) {
    map(g, fn(x) { x / n })
  })
}

pub fn sparsify_kan_layer(layer: KANLayer, sparsity: Float) -> KANLayer {
  let sparse_coeffs = list.map(layer.spline_coeffs, fn(col) {
    list.map(col, fn(c) {
      if float.random() < sparsity { 0.0 } else { c }
    })
  })
  KANLayer(spline_coeffs: sparse_coeffs, grid_size: layer.grid_size, input_dim: layer.input_dim, output_dim: layer.output_dim)
}

pub fn prune_kan_model(network: KANNetwork, sparsity: Float) -> KANNetwork {
  let sparse_layers = list.map(network.layers, fn(l) {
    sparsify_kan_layer(l, sparsity)
  })
  KANNetwork(layers: sparse_layers, dim: network.dim, grid_size: network.grid_size)
}

pub fn profile_kan_forward(network: KANNetwork, input: Matrix, runs: Int) -> #(Float, Float) {
  let start = time.now()
  list.range(0, runs)
  |> list.each(fn(_) {
    kan_forward_pass(network, input)
  })
  let end = time.now()
  let duration = time.diff(end, start)
    |> time.to_milliseconds
    |> float.from_int
    / float.from_int(runs)
  let memory = estimate_kan_memory(network)
  #(duration, memory)
}

fn estimate_kan_memory(network: KANNetwork) -> Float {
  float.from_int(network.dim) * float.from_int(network.grid_size) * float.from_int(list.length(network.layers)) * 8.0
}

pub fn evaluate_model(network: KANNetwork, val_path: String, test_path: String) -> #(Float, Float) {
  let val_dataset = load_dataset_eval(val_path)
  let test_dataset = load_dataset_eval(test_path)
  let val_loss = validate(network, val_dataset)
  let acc = test_accuracy(network, test_dataset)
  #(val_loss, acc)
}

fn load_dataset_eval(path: String) -> List(#(Matrix, Matrix)) {
  let assert Ok(content) = bit_string.from_file(path)
  let assert Ok(decoded) = json.decode(content, dynamic.list(dynamic.dict(dynamic.string, dynamic.dynamic)))
  decoded
  |> list.map(fn(item) {
    let assert Ok(text) = map.get(item, "text") |> result.then(dynamic.string)
    let assert Ok(label) = map.get(item, "label") |> result.then(dynamic.int)
    let dummy_input = random(1, 9216)
    let target = onehot(1, 20, label)
    #(dummy_input, target)
  })
}

pub fn start_server(port: Int) -> Nil {
  io.println("KAN Server started on port " <> string.from_int(port))
  Nil
}

pub type Column {
  Column(active: Bool, cells: List(Cell), proximal_dendrites: List(Segment))
}

pub type Cell {
  Cell(active: Bool, distal_dendrites: List(Segment))
}

pub type Segment {
  Segment(synapses: List(Synapse), permanence: Float)
}

pub type Synapse {
  Synapse(source: Int, permanence: Float)
}

pub fn initialize_htm(columns: Int, cells_per_column: Int) -> List(Column) {
  list.map(list.range(0, columns), fn(_) {
    let cells = list.map(list.range(0, cells_per_column), fn(_) {
      Cell(active: False, distal_dendrites: [Segment(synapses: [], permanence: 0.21)])
    })
    Column(active: False, cells: cells, proximal_dendrites: [Segment(synapses: [], permanence: 0.21)])
  })
}

pub fn compute_spatial_pooling(input: List(Bool), columns: List(Column), connected_pct: Float) -> List(Column) {
  let num_connected = float.round(float.from_int(list.length(columns)) * connected_pct)
  let connected_columns = list.take(list.range(0, list.length(columns)), float.truncate(num_connected))
  list.index_map(columns, fn(idx, col) {
    let active = list.any(input, fn(b) { b }) && idx < float.truncate(num_connected)
    Column(active: active, cells: col.cells, proximal_dendrites: col.proximal_dendrites)
  })
}

pub fn compute_temporal_memory(columns: List(Column), learn: Bool) -> List(Column) {
  list.map(columns, fn(col) {
    let predictive_cells = list.map(col.cells, fn(cell) {
      let active_segments = list.filter(cell.distal_dendrites, fn(seg) {
        list.any(seg.synapses, fn(syn) { syn.permanence > 0.5 })
      })
      Cell(active: list.length(active_segments) > 0, distal_dendrites: cell.distal_dendrites)
    })
    Column(active: col.active, cells: predictive_cells, proximal_dendrites: col.proximal_dendrites)
  })
}

